def max_sum_trionic(nums: list[int]) -> int:
    NEG = float("-inf")
    up1 = down = up2 = NEG  # best sums of each shape ending at the current index
    best = NEG
    for i in range(1, len(nums)):
        a, b = nums[i - 1], nums[i]
        if a < b:
            # climb: extend or start the first rise, extend or start the final rise
            up2 = max(up2, down) + b
            up1 = max(up1, a) + b
            down = NEG
        elif a > b:
            # fall: extend the fall or start it right after a rise
            down = max(down, up1) + b
            up1 = up2 = NEG
        else:
            up1 = down = up2 = NEG
        if up2 > best:
            best = up2
    return int(best)

