    MOD = 10**9 + 7
    n = len(board)
    # extra row and column of -1 act as an unreachable border
    score = [[-1] * (n + 1) for _ in range(n + 1)]
    ways = [[0] * (n + 1) for _ in range(n + 1)]
    score[n - 1][n - 1] = 0
    ways[n - 1][n - 1] = 1
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            cell = board[i][j]
