                continue
            best, count = -1, 0
            for a, b in ((i + 1, j), (i, j + 1), (i + 1, j + 1)):
                s = score[a][b]
                if s > best:
                    best, count = s, ways[a][b]
                elif s == best and s >= 0:
                    count += ways[a][b]
            if best < 0:
                continue  # no reachable predecessor
            score[i][j] = best + (0 if cell == "E" else ord(cell) - 48)
            ways[i][j] = count % MOD
    if score[0][0] < 0:
        return [0, 0]
    return [score[0][0], ways[0][0]]

