class EventEmitter:
    def __init__(self):
        self._events = defaultdict(dict)   # event name -> {id: callback}, in order
        self._next_id = 0

    def subscribe(self, event_name: str, callback: Callable) -> Subscription:
        listeners = self._events[event_name]
        sub_id = self._next_id
        self._next_id += 1
        listeners[sub_id] = callback
        return Subscription(listeners, sub_id)

    def emit(self, event_name: str, args: Optional[List] = None) -> List:
        args = args or []
        listeners = self._events.get(event_name)
        if not listeners:
            return []
        return [callback(*args) for callback in list(listeners.values())]

