class LockingTree:
    def __init__(self, parent: List[int]):
        n = len(parent)
        self.parent = parent
        self.children = [[] for _ in range(n)]
        for node in range(1, n):
            self.children[parent[node]].append(node)
        self.locked_by = [0] * n           # 0 means unlocked

    def lock(self, num: int, user: int) -> bool:
        if self.locked_by[num]:
            return False
        self.locked_by[num] = user
        return True

    def unlock(self, num: int, user: int) -> bool:
        if self.locked_by[num] != user:
            return False
        self.locked_by[num] = 0
        return True

    def upgrade(self, num: int, user: int) -> bool:
        if self.locked_by[num]:
            return False
        # No ancestor may be locked.
        node = self.parent[num]
        while node != -1:
            if self.locked_by[node]:
                return False
            node = self.parent[node]
        # Collect locked descendants.
        locked = []
        stack = list(self.children[num])
        while stack:
            node = stack.pop()
            if self.locked_by[node]:
                locked.append(node)
            stack.extend(self.children[node])
        if not locked:
            return False
        for node in locked:
            self.locked_by[node] = 0
        self.locked_by[num] = user
        return True

