                total += cx * (cx - 1) // 2 * cz
            elif y == z:
                total += cx * cy * (cy - 1) // 2
            else:
                total += cx * cy * cz
    return total % MOD

def num_special(mat: List[List[int]]) -> int:
    row_ones = [sum(row) for row in mat]
    col_ones = [sum(col) for col in zip(*mat)]
    special = 0
    for i, row in enumerate(mat):
        if row_ones[i] != 1:
            continue                     # a special cell needs a row with a single 1
        for j, cell in enumerate(row):
            if cell == 1 and col_ones[j] == 1:
                special += 1
    return special

def check_strings(s1: str, s2: str) -> bool:
    # Even distance swaps keep each character on indices of the same parity,
    # and allow any rearrangement within each parity class.
    return (Counter(s1[0::2]) == Counter(s2[0::2])
            and Counter(s1[1::2]) == Counter(s2[1::2]))

def max_consecutive_answers(answer_key: str, k: int) -> int:
    def longest_run(target: str) -> int:
        best = 0
        left = 0
        bad = 0  # letters inside the window that differ from target
        for right, ch in enumerate(answer_key):
            if ch != target:
                bad += 1
            while bad > k:
                if answer_key[left] != target:
                    bad -= 1
                left += 1
            best = max(best, right - left + 1)
        return best

    return max(longest_run("T"), longest_run("F"))

def max_alternating_sum(nums: List[int]) -> int:
    add = 0  # best sum when the last chosen element is added (odd length)
    sub = 0  # best sum when the last chosen element is subtracted (even length)
    for x in nums:
        add, sub = max(add, sub + x), max(sub, add - x)
    return add

