def share_candies(candies: List[int], k: int) -> int:
    count = Counter(candies)
    kept = len(count)  # flavors with a positive count outside the window

    def take(flavor: int) -> None:
        nonlocal kept
        count[flavor] -= 1
        if count[flavor] == 0:
            kept -= 1

    def give_back(flavor: int) -> None:
        nonlocal kept
        if count[flavor] == 0:
            kept += 1
        count[flavor] += 1

    for i in range(k):
        take(candies[i])
    best = kept
    for right in range(k, len(candies)):
        take(candies[right])
        give_back(candies[right - k])
        best = max(best, kept)
    return best

